import {
    Table,
    StringColumn,
    GuidColumn,
    DateTimeColumn,
    DomainIdColumn,
    DomainPathColumn,
    IntegerColumn,
    ReferenceColumn,
} from '@servicenow/sdk/core'

export const kb_version = Table({
    actions: ['read', 'update', 'create'],
    allowClientScripts: true,
    allowNewFields: true,
    allowUiActions: true,
    allowWebServiceAccess: true,
    display: 'version',
    label: 'Knowledge Version',
    name: 'kb_version',
    schema: {
        version: StringColumn({
            label: 'Version',
        }),
        sys_id: GuidColumn({
            label: [
                {
                    label: 'Sys ID',
                    plural: 'Sys IDs',
                    language: 'en',
                },
            ],
            primary: true,
        }),
        modified_on: DateTimeColumn({
            label: 'Modified On',
        }),
        sys_updated_on: DateTimeColumn({
            label: [
                {
                    label: 'Updated',
                    plural: 'Updated',
                    language: 'en',
                },
            ],
        }),
        sys_domain: DomainIdColumn({
            default: 'global',
            label: [
                {
                    hint: 'Domain to which the article belongs',
                    label: 'Domain',
                    plural: 'Domains',
                    language: 'en',
                },
            ],
        }),
        sys_created_on: DateTimeColumn({
            label: [
                {
                    label: 'Created',
                    plural: 'Created',
                    language: 'en',
                },
            ],
        }),
        sys_domain_path: DomainPathColumn({
            attributes: {
                case_sensitive: true,
            },
            default: '/',
            label: 'Domain Path',
        }),
        sys_mod_count: IntegerColumn({
            label: [
                {
                    label: 'Updates',
                    plural: 'Updates',
                    language: 'en',
                },
            ],
        }),
        knowledge: ReferenceColumn({
            attributes: {
                encode_utf8: false,
                readonly_clickthrough: true,
            },
            cascadeRule: 'delete',
            label: 'Knowledge',
            referenceTable: 'kb_knowledge',
        }),
        modified_by: ReferenceColumn({
            attributes: {
                encode_utf8: false,
            },
            label: 'Modified By',
            referenceTable: 'sys_user',
        }),
        sys_updated_by: StringColumn({
            label: [
                {
                    label: 'Updated by',
                    plural: 'Updated by',
                    language: 'en',
                },
            ],
        }),
        snapshot: IntegerColumn({
            label: 'Snapshot',
        }),
        sys_created_by: StringColumn({
            label: [
                {
                    label: 'Created by',
                    plural: 'Created by',
                    language: 'en',
                },
            ],
        }),
    },
})
